41	const PROCESSING_FEE = 5;
42	const INITIAL_ASSESSMENT_SURCHARGE = 0.1;
43	const CURSE_SURCHARGE = 0.5;
44	const HIGH_ENCHANTMENT_LEVEL = 5;
45	const HIGH_ENCHANTMENT_SURCHARGE = 0.3;
46	const LOYALTY_YEARS = 2;
47	const LOYALTY_DISCOUNT = 0.2;
48	const FOLLOW_UP_CONTRACT_DISCOUNT = 0.15;
49	
50	const BASE_PREMIUMS: Record<string, number> = {
51	  sword: 100,
52	  amulet: 60,
53	  staff: 80,
54	  potion: 40,
55	  rune: 25,
56	  moonstone: 25,
57	};
58	
59	/** Premiums round up: fractions of a Gold piece go to the MHPCO, never the customer. */
60	const roundPremiumInMHPCOFavour = (amount: number): number => Math.ceil(amount);
61	
62	const COMPONENT_BLOCK_SIZE = 3;
63	const COMPONENT_BLOCK_PREMIUM = 60;
64	
65	const countsByType = (items: Item[]): Map<string, number> =>
66	  items.reduce(
67	    (counts, item) => counts.set(item.type, (counts.get(item.type) ?? 0) + 1),
68	    new Map<string, number>(),
69	  );
70	
71	const COMPONENT_TYPES = new Set(["rune", "moonstone"]);
72	
73	/** Exactly three alike components form a building block, priced at a flat rate. */
74	const basePremiumForAlikeItems = (type: string, count: number): number =>
75	  COMPONENT_TYPES.has(type) && count === COMPONENT_BLOCK_SIZE
76	    ? COMPONENT_BLOCK_PREMIUM
77	    : count * BASE_PREMIUMS[type];
78	
79	const policyBasePremium = (items: Item[]): number =>
80	  [...countsByType(items)].reduce(
81	    (total, [type, count]) => total + basePremiumForAlikeItems(type, count),
82	    0,
83	  );
84	
85	/**
86	 * Modifiers are rates on a base premium, never on each other, so each one is
87	 * measured against the same base and the results are summed.
88	 */
89	const amountOf = (rate: number, basePremium: number): number => rate * basePremium;
90	
91	/** Item-specific surcharge rates stack additively on the item's own base premium. */
92	const surchargeRateFor = (item: Item): number =>
93	  (item.cursed ? CURSE_SURCHARGE : 0) +
94	  ((item.enchantment ?? 0) >= HIGH_ENCHANTMENT_LEVEL ? HIGH_ENCHANTMENT_SURCHARGE : 0);
95	
96	/** Item-specific surcharges are rates on the affected item's own base premium. */
97	const itemSurchargeAmount = (items: Item[]): number =>
98	  items.reduce(
99	    (total, item) => total + amountOf(surchargeRateFor(item), BASE_PREMIUMS[item.type]),
100	    0,
101	  );
102	
103	/**
104	 * The facts a policy-wide rate is measured against. Rates key on different
105	 * things — loyalty on the customer's history, the assessment/follow-up rate on
106	 * where the quote falls in the scenario — so they travel together as context.
107	 */
108	interface PolicyContext {
109	  customer: Customer;
110	  /** Zero-based position of this quote among the scenario's quotes. */
111	  quoteOrdinal: number;
112	}
113	
114	/** Policy-wide rates apply to the policy base premium; discounts are negative. */
115	const policyRateFor = ({ customer, quoteOrdinal }: PolicyContext): number =>
116	  INITIAL_ASSESSMENT_SURCHARGE +
117	  (customer.yearsWithMHPCO >= LOYALTY_YEARS ? -LOYALTY_DISCOUNT : 0) +
118	  (quoteOrdinal > 0 ? -FOLLOW_UP_CONTRACT_DISCOUNT : 0);
119	
120	const quote = (step: QuoteStep, policy: PolicyContext): StepResult => {
121	  const base = policyBasePremium(step.items);
122	  const modifiers = itemSurchargeAmount(step.items) + amountOf(policyRateFor(policy), base);
123	  return {
124	    premium: roundPremiumInMHPCOFavour(base + modifiers + PROCESSING_FEE),
125	  };
126	};
127	
128	const runStep = (step: Step, policy: PolicyContext): StepResult => {
129	  if (step.op === "quote") return quote(step, policy);
130	  throw new Error(`Unsupported step: ${step.op}`);
131	};
132	
133	export const runScenario = (scenario: Scenario): ScenarioResult => {
134	  let quotesSoFar = 0;
135	  const results = scenario.steps.map((step) => {
136	    const policy = { customer: scenario.customer, quoteOrdinal: quotesSoFar };
137	    if (step.op === "quote") quotesSoFar += 1;
138	    return runStep(step, policy);
139	  });
140	  return { results };
141	};
