/** How many quotes precede each step — the step's own quote, if any, does not count. */
const quoteOrdinals = (steps: Step[]): number[] =>
  steps.map((_, index) => steps.slice(0, index).filter(isQuote).length);

export const runScenario = (scenario: Scenario): ScenarioResult => {
  const ordinals = quoteOrdinals(scenario.steps);
  const results = scenario.steps.map((step, index) =>
    runStep(step, { customer: scenario.customer, quoteOrdinal: ordinals[index] }),
  );
  return { results };
};

